	InvoiceOperationStatusHeld                  = InvoiceOperationStatus{Code: "HELD", Value: "HELD", Label: "暫停（買家修改中）", Description: "買家送出付款後修改，`held_until = now + 60s`"}
	InvoiceOperationStatusSending               = InvoiceOperationStatus{Code: "SENDING", Value: "SENDING", Label: "送出中", Description: "已 claim，租約 120 秒；租約過期即自動回收"}
	InvoiceOperationStatusRetryScheduled        = InvoiceOperationStatus{Code: "RETRY_SCHEDULED", Value: "RETRY_SCHEDULED", Label: "等待重試", Description: "可重試錯誤，`next_attempt_at = now + 2^attempt × 30s`"}
	InvoiceOperationStatusWaitingConfirmation   = InvoiceOperationStatus{Code: "WAITING_CONFIRMATION", Value: "WAITING_CONFIRMATION", Label: "等待結果確認", Description: "逾時／結果不確定，落在 INV.rc 的候選集合"}
	InvoiceOperationStatusProviderStatusRecheck = InvoiceOperationStatus{Code: "PROVIDER_STATUS_RECHECK", Value: "PROVIDER_STATUS_RECHECK", Label: "重查中", Description: "INV.rc 已 claim，租約 60 秒"}
	InvoiceOperationStatusSucceeded             = InvoiceOperationStatus{Code: "SUCCEEDED", Value: "SUCCEEDED", Label: "已完成", Description: "provider 明確成功（終態）"}
	InvoiceOperationStatusFailedPermanent       = InvoiceOperationStatus{Code: "FAILED_PERMANENT", Value: "FAILED_PERMANENT", Label: "永久失敗", Description: "重試必然再失敗（統編錯／金額不平／字軌不足）；ADM 需先修正資料才可重試"}
