// ===== InvoiceCorrectionStatus =====
// 買家付款後修改發票資料的請求狀態（**6 值**）。與 provider 層的 InvoiceOperationStatus 分開：本值域是「買家看得到的處理進度」，operation 才是「對 AMEGO 的一次呼叫」。⚠️ **沒有 VOID_FAILED**（2026-08-25 依 58 §7.3.6 自值域刪除）：它是陷阱狀態，R05 進得去而兩條出邊 R06／R07 全書沒有任何端點、排程或 MQ consumer 走得到 ⇒ 作廢被 AMEGO 拒絕的請求會永久卡在非終態，而 uq_invcorr_open_per_document 會讓買家再也提不出第二次修改。定版改為 **R05 直接落 REJECTED ＋ reject_reason_code**（三個 f0501 回應碼各自對應一個已存在的拒絕理由，可自動判定、不需人來裁決）。**不要因為「作廢失敗與預檢不通過是兩件事」就把它加回來**——買家看到的答案是同一句，差別只在發現的時點。

type InvoiceCorrectionStatus struct {
	Code        string
	Value       string
	Label       string
	Description string
}

var (
	InvoiceCorrectionStatusRequested             = InvoiceCorrectionStatus{Code: "REQUESTED", Value: "REQUESTED", Label: "已送出", Description: "買家送出，等待預檢"}
	InvoiceCorrectionStatusRejected              = InvoiceCorrectionStatus{Code: "REJECTED", Value: "REJECTED", Label: "已婉拒", Description: "預檢不通過或確認無法修改；reject_reason_code 必填（終態）"}
	InvoiceCorrectionStatusUpdatedBeforeIssue    = InvoiceCorrectionStatus{Code: "UPDATED_BEFORE_ISSUE", Value: "UPDATED_BEFORE_ISSUE", Label: "開立前已更新", Description: "尚未送出 AMEGO，直接改快照並遞增 snapshot_version（終態）"}
	InvoiceCorrectionStatusVoidReissueInProgress = InvoiceCorrectionStatus{Code: "VOID_REISSUE_IN_PROGRESS", Value: "VOID_REISSUE_IN_PROGRESS", Label: "作廢重開處理中", Description: "已開立，預檢通過，正在作廢並重開"}
	InvoiceCorrectionStatusReissueFailed         = InvoiceCorrectionStatus{Code: "REISSUE_FAILED", Value: "REISSUE_FAILED", Label: "重開失敗（買家手上無憑證）", Description: "**最高優先級**：原發票已作廢、新發票不存在。獨立 ADM 佇列 ＋ 15 分鐘告警。⚠️ 與已刪除的 VOID_FAILED 的根本差別：本值買家手上一張憑證都沒有，作廢被拒時原發票仍然有效"}
	InvoiceCorrectionStatusCompleted             = InvoiceCorrectionStatus{Code: "COMPLETED", Value: "COMPLETED", Label: "已完成", Description: "作廢與重開皆成功，原件已轉 SUPERSEDED（終態）"}
)

var AllInvoiceCorrectionStatuss = []InvoiceCorrectionStatus{
	InvoiceCorrectionStatusRequested,
	InvoiceCorrectionStatusRejected,
	InvoiceCorrectionStatusUpdatedBeforeIssue,
	InvoiceCorrectionStatusVoidReissueInProgress,
	InvoiceCorrectionStatusReissueFailed,
	InvoiceCorrectionStatusCompleted,
}

