	ResponsibilityCauseSellerCaused   = ResponsibilityCause{Code: "SELLER_CAUSED", Value: "SELLER_CAUSED", Label: "賣家原因", Description: "由賣家負擔（備貨逾時、地址填錯、商品不符等）"}
	ResponsibilityCauseBuyerCaused    = ResponsibilityCause{Code: "BUYER_CAUSED", Value: "BUYER_CAUSED", Label: "買家原因", Description: "🔴 **仍歸賣家的物流成本**；平台**不得**向買家二次收款（買家已完成一次付款，ADR-004）"}
	ResponsibilityCausePlatformCaused = ResponsibilityCause{Code: "PLATFORM_CAUSED", Value: "PLATFORM_CAUSED", Label: "平台或系統原因", Description: "🔴 平台負擔，**不得轉嫁賣家**。這一格是唯一會 post `COLLECTION_FEE_ACCRUAL` 的情況。⚠️ **系統原因也歸這一格**——`SYSTEM_CAUSED` 不存在，不得新增"}
	ResponsibilityCauseProviderCaused = ResponsibilityCause{Code: "PROVIDER_CAUSED", Value: "PROVIDER_CAUSED", Label: "物流商原因", Description: "🔴 **不得自動向賣家收**，先進爭議／對帳。⚠️ **不再是「判定原料不足」的 fail-closed 落點**（2026-09-17 廢除，見上方說明）——證據不足時案件留在 `IN_PROGRESS`，不落任何成因"}
